//! Expression + statement emitters.
//!
//! Every emit function returns a JS source fragment (`String`).
//!
//! Convention:
//! - Expression emitters return a fragment that evaluates to a value
//!   (no `;`, no statements).
//! - Statement emitters may return multi-line fragments terminated by `;`
//!   or `}`. They rely on `__out.push(...)` / `__strict` being in scope
//!   (established by [`super::codegen`]).
//! - Temporary variables use `__v`, `__v1`, `__v2` ... names generated by
//!   [`CodegenCtx::next_temp`].
//!
//! Caller-owned state lives in [`CodegenCtx`]. Diagnostic collection, strict
//! mode, entry template id, and a temp counter are all fields on it.
//!
//! Catalog-aware mode (`CatalogEmitCtx`):
//! When a template is compiled as part of a catalog AOT run the caller
//! provides merged block definitions, parent block definitions (for `super`
//! inlining), and a per-include resolver. This lets `Stmt.Block`,
//! `Stmt.Super`, and `Stmt.Include` emit meaningful JS instead of throwing.

use once_cell::sync::Lazy;
use serde::Serialize;
use serde_json::Value;
use std::collections::{HashMap, HashSet};

use dejavu_diagnostic::{ArgValue, Diagnostic, Severity, Span, Stage, codes};
use dejavu_ir::registry::{
    Capability, CapabilitySet, CustomEntry, FilterLookupError, FunctionLookupError, Namespace,
    TestLookupError, custom_entry, validate_custom_entries, validate_filter, validate_function,
    validate_test,
};
use dejavu_ir::IrNode;

use crate::options::CodegenOptions;

// ---------------------------------------------------------------------------
// JavaScript reserved words (ES6+ — strict mode safe).
//
// Identifier emit must fall back to `ctx["..."]` for any of these.
// Future reserved words are also included (`implements`, `interface`,
// `package`, `private`, `protected`, `public`, `enum`, `await`, `yield`)
// so generated code runs cleanly in strict mode and inside async/generators.
// ---------------------------------------------------------------------------

static JS_RESERVED: Lazy<HashSet<&'static str>> = Lazy::new(|| {
    let mut s = HashSet::new();
    for w in [
        // Keywords.
        "break", "case", "catch", "class", "const", "continue", "debugger", "default", "delete", "do",
        "else", "enum", "export", "extends", "false", "finally", "for", "function", "if", "import",
        "in", "instanceof", "new", "null", "return", "super", "switch", "this", "throw", "true",
        "try", "typeof", "var", "void", "while", "with", "yield",
        // ES module context: `await` is a reserved word at module top level.
        "await",
        // Future reserved.
        "implements", "interface", "package", "private", "protected", "public",
    ] {
        s.insert(w);
    }
    s
});

/// Is `name` a JavaScript reserved / future-reserved word?
pub fn is_reserved(name: &str) -> bool {
    JS_RESERVED.contains(name)
}

// ---------------------------------------------------------------------------
// Line origins
// ---------------------------------------------------------------------------

/// One generated JS line that starts a template construct.
///
/// `line` is 0-based inside the emitted *module body*. Callers add the module
/// header offset before turning these into source-map entries.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct LineOrigin {
    /// Generated line index (0-based bytes counted by `\n`).
    pub line: u32,
    /// Template byte offset where the construct starts.
    pub start: u32,
    /// Template byte offset where the construct ends (exclusive).
    pub end: u32,
}

// ---------------------------------------------------------------------------
// CodegenCtx
// ---------------------------------------------------------------------------

/// Shared mutable state for the emitters.
pub struct CodegenCtx<'a> {
    pub options: &'a CodegenOptions,
    /// Collected diagnostics (errors + warnings about unsupported nodes etc.).
    pub diagnostics: Vec<Diagnostic>,
    /// Generated-line → template-span points, in emission order.
    pub origins: Vec<LineOrigin>,
    /// Monotonic counter for `__vN` temp variables.
    temp_counter: u32,
    /// Ancestor bodies of the block currently being emitted (most-derived first).
    /// `super` consumes `super_index` and advances one level up.
    super_chain: Vec<Vec<IrNode>>,
    /// Index inside `super_chain` that the next `super` should inline.
    super_index: usize,
    /// Local macro name → JS function binding (declared or imported).
    pub macros: HashMap<String, String>,
    /// JS expression for the next macro call's depth counter.
    macro_depth_expr: String,
    /// True while emitting a macro body, where `caller()` may be emitted.
    pub in_macro: bool,
    /// Registry capabilities granted to the compiled artifact.
    capabilities: CapabilitySet,
    /// Host-supplied entries, validated once by [`CodegenCtx::new`].
    custom_registry: &'a [CustomEntry],
}

impl<'a> CodegenCtx<'a> {
    pub fn new(options: &'a CodegenOptions) -> Self {
        let mut diagnostics = Vec::new();
        // A rejected registry is a configuration error about the whole compile,
        // reported before any template name is resolved. Reuse the JIT
        // diagnostic code/args, only restating the stage as `Compile`.
        if let Err(mut diagnostic) = validate_custom_entries(&options.custom_registry) {
            diagnostic.stage = Stage::Compile;
            diagnostics.push(diagnostic);
        }
        let capabilities = match options.capability_set() {
            Ok(set) => set,
            Err(name) => {
                // Keep emitting with the unrestricted set so the configuration
                // error stays the only diagnostic instead of cascading denials.
                diagnostics.push(
                    Diagnostic::new(Severity::Error, codes::UNKNOWN_CAPABILITY, Stage::Compile)
                        .message(format!("unknown capability `{name}`"))
                        .arg("capability", name),
                );
                CapabilitySet::all()
            }
        };
        Self {
            options,
            diagnostics,
            capabilities,
            origins: Vec::new(),
            temp_counter: 0,
            super_chain: Vec::new(),
            super_index: 0,
            macros: HashMap::new(),
            macro_depth_expr: "1".into(),
            in_macro: false,
            custom_registry: &options.custom_registry,
        }
    }

    /// Register the module's macro names so calls emit macro functions instead
    /// of registry function calls.
    pub fn set_macros(&mut self, names: impl IntoIterator<Item = String>) {
        self.macros = names.into_iter().map(|n| (n.clone(), macro_fn_name(&n))).collect();
    }

    /// Bind a local macro name to an imported JS function.
    pub fn set_macro_ref(&mut self, local: &str, js: &str) {
        self.macros.insert(local.to_string(), js.to_string());
    }

    /// JS binding for a macro call, if `name` is a macro in this module.
    pub fn macro_ref(&self, name: &str) -> Option<&str> {
        self.macros.get(name).map(String::as_str)
    }

    /// Does `name` resolve to a macro in the module being emitted?
    pub fn is_macro(&self, name: &str) -> bool {
        self.macros.contains_key(name)
    }

    /// Return the next unique temp variable name (`__v`, `__v1`, `__v2`, ...).
    pub fn next_temp(&mut self) -> String {
        let n = self.temp_counter;
        self.temp_counter += 1;
        if n == 0 { "__v".into() } else { format!("__v{n}") }
    }

    /// Emit a structured Diagnostic at compile stage.
    pub fn diagnostic(
        &mut self,
        severity: Severity,
        code: impl Into<String>,
        message: impl Into<String>,
    ) {
        self.diagnostics.push(
            Diagnostic::new(severity, code, Stage::Compile).message(message),
        );
    }

    /// Emit a Diagnostic with an `args` keyed payload.
    pub fn diagnostic_arg(
        &mut self,
        severity: Severity,
        code: impl Into<String>,
        message: impl Into<String>,
        key: impl Into<String>,
        value: impl Into<ArgValue>,
    ) {
        self.diagnostics.push(
            Diagnostic::new(severity, code, Stage::Compile)
                .message(message)
                .arg(key, value),
        );
    }

    /// Emit `capability-not-allowed` for a registry entry the host denied.
    fn capability_denied(&mut self, name: &str, capability: Capability) {
        self.diagnostic_args(
            Severity::Error,
            codes::CAPABILITY_NOT_ALLOWED,
            format!("`{name}` requires the `{}` capability", capability.as_str()),
            [("name", ArgValue::from(name)), ("capability", ArgValue::from(capability.as_str()))],
        );
    }

    /// Resolve a host-supplied entry after the built-in lookup reported `Unknown`.
    ///
    /// The returned entry is owned so diagnostics can be recorded afterwards.
    /// Aliases resolve to the canonical entry; callers emit `entry.name` only.
    fn custom_lookup(&self, namespace: Namespace, name: &str) -> Option<CustomEntry> {
        custom_entry(self.custom_registry, namespace, name).cloned()
    }

    /// Check a host-supplied entry's arity and capability.
    ///
    /// `code` is the namespace's existing arity code and `key` its `args` key
    /// (`filter` / `function` / `test`) so custom entries reuse the built-in
    /// contract instead of introducing new codes. Returns `false` when a
    /// diagnostic was emitted.
    fn accepts_custom(
        &mut self,
        entry: &CustomEntry,
        arg_count: usize,
        code: &'static str,
        key: &'static str,
    ) -> bool {
        if arg_count < entry.min_args || arg_count > entry.max_args {
            self.diagnostic_args(
                Severity::Error,
                code,
                format!(
                    "{} `{}` expects {}..{} argument(s), got {arg_count}",
                    entry.namespace.as_str(),
                    entry.name,
                    entry.min_args,
                    entry.max_args
                ),
                [
                    (key, ArgValue::String(entry.name.clone())),
                    ("minArgs", ArgValue::Number(entry.min_args as f64)),
                    ("maxArgs", ArgValue::Number(entry.max_args as f64)),
                    ("got", ArgValue::Number(arg_count as f64)),
                ],
            );
            return false;
        }
        if !self.capabilities.allows(entry.capability) {
            self.capability_denied(&entry.name, entry.capability);
            return false;
        }
        true
    }

    /// Emit a Diagnostic with several structured `args`.
    pub fn diagnostic_args(
        &mut self,
        severity: Severity,
        code: impl Into<String>,
        message: impl Into<String>,
        args: impl IntoIterator<Item = (&'static str, ArgValue)>,
    ) {
        let mut diagnostic = Diagnostic::new(severity, code, Stage::Compile).message(message);
        for (key, value) in args {
            diagnostic = diagnostic.arg(key, value);
        }
        self.diagnostics.push(diagnostic);
    }

    /// Extract a `Span` from an IrNode (best-effort; not all nodes carry one).
    pub fn span_of(node: &IrNode) -> Option<Span> {
        match node {
            IrNode::Template { span, .. }
            | IrNode::Text { span, .. }
            | IrNode::Comment { span, .. }
            | IrNode::Interpolation { span, .. }
            | IrNode::StmtIf { span, .. }
            | IrNode::StmtElseIf { span, .. }
            | IrNode::StmtFor { span, .. }
            | IrNode::StmtBlock { span, .. }
            | IrNode::StmtPartial { span, .. }
            | IrNode::StmtMacro { span, .. }
            | IrNode::StmtImport { span, .. }
            | IrNode::StmtCall { span, .. }
            | IrNode::StmtExtends { span, .. }
            | IrNode::StmtInclude { span, .. }
            | IrNode::StmtSuper { span, .. }
            | IrNode::StmtRaw { span, .. }
            | IrNode::ExprLiteral { span, .. }
            | IrNode::ExprIdentifier { span, .. }
            | IrNode::ExprMember { span, .. }
            | IrNode::ExprIndex { span, .. }
            | IrNode::ExprCall { span, .. }
            | IrNode::ExprTest { span, .. }
            | IrNode::ExprBinary { span, .. }
            | IrNode::ExprUnary { span, .. }
            | IrNode::ExprObject { span, .. }
            | IrNode::ExprPipe { span, .. } => span.as_ref().map(|s| Span::new(s.start, s.end)),
        }
    }
}

// ---------------------------------------------------------------------------
// Expression emit
// ---------------------------------------------------------------------------

/// Emit an expression as a JS source fragment.
///
/// Returns something like `ctx.name`, `binary("+", 1, 2)`, `exprMember(ctx, "a")`.
/// Callers must supply their own `;` if they use this as a statement.
pub fn emit_expr(node: &IrNode, ctx: &mut CodegenCtx) -> String {
    match node {
        IrNode::ExprLiteral { value, .. } => emit_json_value(value),
        IrNode::ExprIdentifier { name, .. } => emit_identifier(name),
        IrNode::ExprMember { object, property, .. } => {
            let obj = emit_expr(object, ctx);
            format!("exprMember({obj}, {})", json_string(property))
        }
        IrNode::ExprIndex { object, index, .. } => {
            let obj = emit_expr(object, ctx);
            let idx = emit_expr(index, ctx);
            format!("exprIndex({obj}, {idx})")
        }
        IrNode::ExprBinary { operator, left, right, .. } => {
            let l = emit_expr(left, ctx);
            let r = emit_expr(right, ctx);
            format!("binary({}, {l}, {r})", json_string(operator))
        }
        IrNode::ExprUnary { operator, argument, .. } => {
            let a = emit_expr(argument, ctx);
            format!("unary({}, {a})", json_string(operator))
        }
        IrNode::ExprObject { entries, .. } => {
            let parts: Vec<String> = entries
                .iter()
                .map(|entry| format!("{}: {}", json_string(&entry.key), emit_expr(&entry.value, ctx)))
                .collect();
            format!("{{ {} }}", parts.join(", "))
        }
        IrNode::ExprPipe { expression, filter, arguments, .. } => {
            // Pipes are emitted as a temp var chain so multi-filter pipes stay readable:
            //   let __v = <expr>;
            //   __v = applyFilter("f1", __v, []);
            //   __v = applyFilter("f2", __v, []);
            // The single-filter case we inline directly as a single applyFilter call
            // so we don't always need a temp for simple pipes.
            //
            // But wait — the "expression" of the pipe IS the prior node; nested pipes
            // mean expression is itself an ExprPipe. We walk inward recursively; each
            // level will return either a raw fragment or the __v we assigned.
            //
            // To keep call-sites simple we emit as an applyFilter chain that uses a
            // single fresh temp. The expression is evaluated once; each filter wraps
            // it. For code readability we emit the entire chain as a statement-like
            // thing... but emit_expr must return a single expression fragment.
            //
            // Compromise: emit_expr for ExprPipe returns
            //   `( /* side-effect __v assignments captured by temp var, we inline */ applyFilter("last", ...) )`
            //
            // Actually the simplest correct approach: emit the full pipe as
            //   applyFilter("last", applyFilter("middle", applyFilter("first", <root>, [...args]), [...args]), [...args])
            // That's JS expression-safe. Decision doc says "链式 pipe 需要临时变量"
            // but for expression-context emit we can nest. We *will* use a temp in
            // statement context where we control `__out.push(...)` placement.
            //
            // So here: nest.

            let inner = emit_expr(expression, ctx);
            let args_str = emit_expr_list(arguments, ctx);
            // Validate against the language-neutral registry at compile time so
            // AOT output never contains an unknown or mis-arity filter. Names the
            // built-in table does not know resolve against host-supplied entries,
            // and are emitted under their canonical name (aliases never reach the
            // runtime).
            let mut emitted = filter.clone();
            match validate_filter(filter, arguments.len(), ctx.capabilities) {
                Ok(_) => {}
                Err(FilterLookupError::NotAllowed { spec }) => {
                    ctx.capability_denied(spec.name, spec.capability);
                }
                Err(FilterLookupError::Unknown) => match ctx.custom_lookup(Namespace::Filter, filter) {
                    Some(entry) => {
                        emitted = entry.name.clone();
                        ctx.accepts_custom(&entry, arguments.len(), codes::FILTER_ARITY, "filter");
                    }
                    None => ctx.diagnostic_arg(
                        Severity::Error,
                        codes::UNKNOWN_FILTER,
                        format!("unknown filter `{filter}`"),
                        "filter",
                        filter.clone(),
                    ),
                },
                Err(FilterLookupError::Arity { spec }) => ctx.diagnostic_args(
                    Severity::Error,
                    codes::FILTER_ARITY,
                    format!(
                        "filter `{}` expects {}..{} argument(s), got {}",
                        spec.name,
                        spec.min_args,
                        spec.max_args,
                        arguments.len()
                    ),
                    [
                        ("filter", ArgValue::String(spec.name.to_string())),
                        ("minArgs", ArgValue::Number(spec.min_args as f64)),
                        ("maxArgs", ArgValue::Number(spec.max_args as f64)),
                        ("got", ArgValue::Number(arguments.len() as f64)),
                    ],
                ),
            }
            format!(
                "applyFilter({}, {inner}, [{args_str}], __custom)",
                json_string(&emitted)
            )
        }
        IrNode::ExprCall { callee, arguments, .. } => {
            // Only a bare identifier that resolves to the language-neutral
            // function registry may execute. Member calls and unknown names
            // stay closed — never emit a host call.
            let IrNode::ExprIdentifier { name, .. } = callee.as_ref() else {
                ctx.diagnostic_arg(
                    Severity::Error,
                    codes::CALLS_NOT_SUPPORTED,
                    "dejavu-codegen: only built-in function calls are supported",
                    "callee",
                    format!("{callee:?}"),
                );
                // Keep the module syntactically valid so diagnostics still print.
                emit_expr(callee, ctx);
                emit_expr_list(arguments, ctx);
                return "null".into();
            };
            // A macro in the same module wins over a registry function of the
            // same name (the parser/renderer reject such a conflict at compile
            // time, so this branch is unambiguous).
            if let Some(js_fn) = ctx.macro_ref(name) {
                let js_fn = js_fn.to_string();
                let args_s = emit_expr_list(arguments, ctx);
                return format!(
                    "{js_fn}(ctx, [{args_s}], {}, __strict, null, __custom)",
                    ctx.macro_depth_expr
                );
            }
            // `caller(args)` renders the block supplied by the enclosing
            // `call`. Arity is checked by the emitted closure, because one
            // macro may be reached through `call` sites declaring different
            // caller parameters.
            if name == "caller" {
                if !ctx.in_macro {
                    ctx.diagnostic(
                        Severity::Error,
                        codes::CALLER_UNAVAILABLE,
                        "`caller()` is only available inside a macro invoked by `call`",
                    );
                    return "null".into();
                }
                if arguments.is_empty() {
                    return "__caller()".into();
                }
                return format!("__caller([{}])", emit_expr_list(arguments, ctx));
            }
            let args_s = emit_expr_list(arguments, ctx);
            match validate_function(name, arguments.len(), ctx.capabilities) {
                Ok(spec) => format!(
                    "callFunction({}, [{args_s}], __custom)",
                    json_string(spec.name)
                ),
                Err(FunctionLookupError::NotAllowed { spec }) => {
                    ctx.capability_denied(spec.name, spec.capability);
                    "null".into()
                }
                Err(FunctionLookupError::Unknown) => {
                    match ctx.custom_lookup(Namespace::Function, name) {
                        Some(entry) => {
                            let canonical = entry.name.clone();
                            if ctx.accepts_custom(
                                &entry,
                                arguments.len(),
                                codes::FUNCTION_ARITY,
                                "function",
                            ) {
                                format!("callFunction({}, [{args_s}], __custom)", json_string(&canonical))
                            } else {
                                "null".into()
                            }
                        }
                        None => {
                            ctx.diagnostic_arg(
                                Severity::Error,
                                codes::UNKNOWN_FUNCTION,
                                format!("unknown function `{name}`"),
                                "function",
                                name.clone(),
                            );
                            "null".into()
                        }
                    }
                }
                Err(FunctionLookupError::Arity { spec }) => {
                    ctx.diagnostic_args(
                        Severity::Error,
                        codes::FUNCTION_ARITY,
                        format!(
                            "function `{}` expects {}..{} argument(s), got {}",
                            spec.name,
                            spec.min_args,
                            spec.max_args,
                            arguments.len()
                        ),
                        [
                            ("function", ArgValue::String(spec.name.to_string())),
                            ("minArgs", ArgValue::Number(spec.min_args as f64)),
                            ("maxArgs", ArgValue::Number(spec.max_args as f64)),
                            ("got", ArgValue::Number(arguments.len() as f64)),
                        ],
                    );
                    "null".into()
                }
            }
        }
        IrNode::ExprTest { expression, test, arguments, negated, .. } => {
            let inner = emit_expr(expression, ctx);
            let args_s = emit_expr_list(arguments, ctx);
            match validate_test(test, arguments.len(), ctx.capabilities) {
                Ok(spec) => format!(
                    "applyTest({}, {inner}, [{args_s}], {negated}, __custom)",
                    json_string(spec.name)
                ),
                Err(TestLookupError::NotAllowed { spec }) => {
                    ctx.capability_denied(spec.name, spec.capability);
                    "null".into()
                }
                Err(TestLookupError::Unknown) => match ctx.custom_lookup(Namespace::Test, test) {
                    Some(entry) => {
                        let canonical = entry.name.clone();
                        if ctx.accepts_custom(&entry, arguments.len(), codes::TEST_ARITY, "test") {
                            format!(
                                "applyTest({}, {inner}, [{args_s}], {negated}, __custom)",
                                json_string(&canonical)
                            )
                        } else {
                            "null".into()
                        }
                    }
                    None => {
                        ctx.diagnostic_arg(
                            Severity::Error,
                            codes::UNKNOWN_TEST,
                            format!("unknown test `{test}`"),
                            "test",
                            test.clone(),
                        );
                        "null".into()
                    }
                },
                Err(TestLookupError::Arity { spec }) => {
                    ctx.diagnostic_args(
                        Severity::Error,
                        codes::TEST_ARITY,
                        format!(
                            "test `{}` expects {}..{} argument(s), got {}",
                            spec.name,
                            spec.min_args,
                            spec.max_args,
                            arguments.len()
                        ),
                        [
                            ("test", ArgValue::String(spec.name.to_string())),
                            ("minArgs", ArgValue::Number(spec.min_args as f64)),
                            ("maxArgs", ArgValue::Number(spec.max_args as f64)),
                            ("got", ArgValue::Number(arguments.len() as f64)),
                        ],
                    );
                    "null".into()
                }
            }
        }
        // Anything else used as expression (Template, Text, ...) is nonsensical —
        // emit a JS null with a diagnostic so the module still parses.
        _ => {
            ctx.diagnostic(
                Severity::Error,
                "dejavu.compile.invalid-expression-node",
                "node used as expression position",
            );
            "null".into()
        }
    }
}

/// Emit a JSON value as a JS literal.
///
/// Numbers bypass stringify to avoid accidentally quoting them; strings use
/// `serde_json::to_string` (which produces the correct JS-quoted-and-escaped
/// form). Arrays/objects recurse.
pub fn emit_json_value(v: &Value) -> String {
    match v {
        Value::Null => "null".into(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => {
            // n is already stored as the original JSON number string.
            // For safety we still guard against pathological f64 representations.
            n.as_f64().map(|f| format_js_number(f)).unwrap_or_else(|| n.to_string())
        }
        Value::String(s) => json_string(s),
        Value::Array(arr) => {
            let items: Vec<String> = arr.iter().map(emit_json_value).collect();
            format!("[{}]", items.join(", "))
        }
        Value::Object(map) => {
            let entries: Vec<String> = map
                .iter()
                .map(|(k, v)| format!("{}: {}", json_string(k), emit_json_value(v)))
                .collect();
            format!("{{{}}}", entries.join(", "))
        }
    }
}

/// Format an f64 as a clean JS number. Avoids `NaN`, `Infinity`, `-Infinity`
/// (JSON number parsing in serde_json would already reject these, but be safe).
fn format_js_number(f: f64) -> String {
    if f.is_nan() {
        return "NaN".into();
    }
    if f.is_infinite() {
        return if f > 0.0 { "Infinity" } else { "-Infinity" }.into();
    }
    // Rust's f64 Display gives us the shortest representation that round-trips.
    // JavaScript toString is compatible for finite values.
    f.to_string()
}

/// Emit a JS identifier expression. Handles reserved-word escape.
pub fn emit_identifier(name: &str) -> String {
    if is_reserved(name) {
        format!("ctx[{}]", json_string(name))
    } else {
        format!("ctx.{name}")
    }
}

/// Emit a JSON string literal (JS-safe, including quote handling).
pub fn json_string(s: &str) -> String {
    // serde_json::to_string on &str is `"..."` with proper JS escaping.
    serde_json::to_string(s).expect("str always serializes")
}

/// Emit a comma-separated JS expression list (for filter args / call args).
pub fn emit_expr_list(items: &[IrNode], ctx: &mut CodegenCtx) -> String {
    items.iter().map(|n| emit_expr(n, ctx)).collect::<Vec<_>>().join(", ")
}

// ---------------------------------------------------------------------------
// Catalog-aware context (only populated during precompile_catalog)
// ---------------------------------------------------------------------------

/// Extra state supplied by `precompile_catalog` so that Stmt.Block /
/// Stmt.Super / Stmt.Include can emit real JS instead of throwing.
///
/// Single-template mode passes `None`.
pub struct CatalogEmitCtx<'a> {
    /// Every ancestor definition of each block, most-derived first. Index 0 is
    /// the effective body, each further index is one `super` hop up.
    pub block_chains: &'a HashMap<String, Vec<Vec<IrNode>>>,
    /// Map from include literal path → canonical template id. Populated
    /// during precompile_catalog's edge resolution so emit time only does
    /// lookup, no catalog traversal.
    pub include_imports: &'a HashMap<String, String>,
    /// Canonical ids of templates declared as `partial`. Includes of these
    /// bind only the explicit `with` object, never the caller context.
    pub partial_ids: &'a HashSet<String>,
}

// ---------------------------------------------------------------------------
// Statement emit
// ---------------------------------------------------------------------------

/// Record where this node's output starts, so source maps can point at it.
///
/// Comments emit nothing and therefore have no line. Nested bodies are recorded
/// by their own `emit_stmt` calls, so every entry covers exactly one construct.
fn record_origin(node: &IrNode, out: &str, ctx: &mut CodegenCtx) {
    if matches!(node, IrNode::Comment { .. }) {
        return;
    }
    let Some(span) = CodegenCtx::span_of(node) else {
        return;
    };
    let line = out.bytes().filter(|b| *b == b'\n').count();
    ctx.origins.push(LineOrigin {
        line: u32::try_from(line).unwrap_or(u32::MAX),
        start: u32::try_from(span.start).unwrap_or(u32::MAX),
        end: u32::try_from(span.end).unwrap_or(u32::MAX),
    });
}

/// Emit a sequence of top-level body nodes (Template.children, If.consequent, ...).
///
/// `catalog` is `None` in single-template mode (Stmt.Block/Extends/Include/Super
/// fall back to the "not supported" throw path). In catalog mode it supplies
/// merged block definitions and include import bindings.
pub fn emit_body(
    nodes: &[IrNode],
    ctx: &mut CodegenCtx,
    out: &mut String,
    catalog: Option<&CatalogEmitCtx>,
) {
    // Apply the whitespace-control contract before emitting text so AOT output
    // matches the interpreter byte for byte.
    let nodes = dejavu_ir::trim::normalized_children(nodes);
    for n in &nodes {
        emit_stmt(n, ctx, out, catalog);
    }
}

/// Emit a single statement-style IrNode. Appends directly to `out`.
pub fn emit_stmt(
    node: &IrNode,
    ctx: &mut CodegenCtx,
    out: &mut String,
    catalog: Option<&CatalogEmitCtx>,
) {
    record_origin(node, out, ctx);
    match node {
        IrNode::Text { value, .. } => {
            out.push_str("__out.push(");
            out.push_str(&json_string(value));
            out.push_str(");\n");
        }
        IrNode::Comment { .. } => {
            // Skipped — not in emitted JS output.
        }
        IrNode::Interpolation { expression, raw, trim: _, .. } => {
            emit_interpolation(expression, *raw, ctx, out);
        }
        IrNode::StmtIf { test, consequent, else_ifs, alternate, .. } => {
            emit_if(test, consequent, else_ifs, alternate.as_deref(), ctx, out, catalog);
        }
        IrNode::StmtFor { item, index, iterable, body, .. } => {
            emit_for(item, index.as_deref(), iterable, body, ctx, out, catalog);
        }
        IrNode::StmtRaw { value, .. } => {
            // Raw block: emit literal text into __out.
            out.push_str("__out.push(");
            out.push_str(&json_string(value));
            out.push_str(");\n");
        }
        IrNode::StmtBlock { name, body, .. } => {
            emit_block(name, body, ctx, out, catalog);
        }
        IrNode::StmtPartial { params, body, .. } => {
            emit_partial(params, body, ctx, out, catalog);
        }
        // Macro definitions are hoisted into module-level functions by
        // `precompile`; the declaration itself emits no output.
        IrNode::StmtMacro { .. } => {}
        // Macro imports become ESM imports in `build_module`.
        IrNode::StmtImport { .. } => {}
        // `call name(args)` … `end call`: pass the caller block as a closure
        // so it renders in the calling scope, not the macro's. Declared caller
        // parameters are bound onto a copy of that scope.
        IrNode::StmtCall { name, arguments, params, body, .. } => {
            let Some(js_fn) = ctx.macro_ref(name).map(str::to_string) else {
                ctx.diagnostic_arg(
                    Severity::Error,
                    codes::UNKNOWN_FUNCTION,
                    format!("unknown macro `{name}` in `call`"),
                    "function",
                    name.clone(),
                );
                return;
            };
            let args_s = emit_expr_list(arguments, ctx);
            let mut caller_body = String::new();
            emit_body(body, ctx, &mut caller_body, catalog);
            let depth = ctx.macro_depth_expr.clone();
            let count = params.len();
            let guard = format!(
                "if ((__callerArgs == null ? 0 : __callerArgs.length) !== {count}) {{ const __got = __callerArgs == null ? 0 : __callerArgs.length; throw runtimeError(\"dejavu.template.caller-arity\", \"`caller()` expects {count} argument(s), got \" + __got, {{ got: __got, maxArgs: {count} }}); }}\n"
            );
            out.push_str(&format!(
                "__out.push({js_fn}(ctx, [{args_s}], {depth}, __strict, function (__callerArgs) {{\n{guard}"
            ));
            if count == 0 {
                out.push_str("const __out = [];\n");
                out.push_str(&caller_body);
                out.push_str("return __out.join(\"\");\n}, __custom));\n");
            } else {
                let bindings = params
                    .iter()
                    .enumerate()
                    .map(|(idx, param)| format!("{}: __callerArgs[{idx}]", json_string(&param.name)))
                    .collect::<Vec<_>>()
                    .join(", ");
                out.push_str(&format!(
                    "return (function (ctx) {{\nconst __out = [];\n"
                ));
                out.push_str(&caller_body);
                out.push_str(&format!(
                    "return __out.join(\"\");\n}})(Object.assign({{}}, ctx, {{ {bindings} }}));\n}}, __custom));\n"
                ));
            }
        }
        IrNode::StmtExtends { .. } => {
            // In catalog mode the extends chain is flattened before we reach
            // emit — we should never land here. In single-template mode it's
            // a hard "not supported".
            match catalog {
                Some(_) => ctx.diagnostic(
                    Severity::Warning,
                    "dejavu.compile.unexpected-extends-in-emitted-body",
                    "Stmt.Extends should have been flattened before emit",
                ),
                None => emit_not_supported("Stmt.Extends", None, ctx, out),
            }
        }
        IrNode::StmtInclude { path, with, only, .. } => {
            emit_include(path, with.as_deref(), *only, ctx, out, catalog);
        }
        IrNode::StmtSuper { .. } => {
            emit_super(ctx, out, catalog);
        }
        IrNode::Template { children, .. } => {
            // Nested template — emit its children directly (no extra wrapper).
            emit_body(children, ctx, out, catalog);
        }
        // Expression used as a top-level statement? Not supported in dejavu IR
        // semantics, but be tolerant: emit as `__out.push(<expr>)` so it still
        // produces runtime output and surfaces the issue via diagnostics.
        _ => {
            ctx.diagnostic(
                Severity::Warning,
                "dejavu.compile.expression-as-statement",
                "expression used as top-level statement",
            );
            let e = emit_expr(node, ctx);
            out.push_str("__out.push(valueToString(");
            out.push_str(&e);
            out.push_str("));\n");
        }
    }
}

// ---------------------------------------------------------------------------
// Catalog-aware Block / Include / Super emit
// ---------------------------------------------------------------------------

fn emit_block(
    name: &str,
    original_body: &[IrNode],
    ctx: &mut CodegenCtx,
    out: &mut String,
    catalog: Option<&CatalogEmitCtx>,
) {
    if let Some(cat) = catalog {
        // Index 0 is the effective body; `super` then walks the chain upward.
        let chain = cat
            .block_chains
            .get(name)
            .cloned()
            .unwrap_or_else(|| vec![original_body.to_vec()]);
        let saved_chain = std::mem::replace(&mut ctx.super_chain, chain.clone());
        let saved_index = ctx.super_index;
        ctx.super_index = 1;
        emit_body(&chain[0], ctx, out, Some(cat));
        ctx.super_index = saved_index;
        ctx.super_chain = saved_chain;
    } else {
        emit_not_supported("Stmt.Block", Some(name), ctx, out);
    }
}

fn emit_partial(
    params: &[dejavu_ir::types::PartialParam],
    body: &[IrNode],
    ctx: &mut CodegenCtx,
    out: &mut String,
    catalog: Option<&CatalogEmitCtx>,
) {
    // A partial binds exactly its declared parameters. The caller context is
    // not visible inside the body, and undeclared parameters are rejected.
    let saved = ctx.next_temp();
    let names = ctx.next_temp();
    out.push_str("{\n");
    out.push_str(&format!("const {saved} = ctx;\n"));
    let names_literal: Vec<String> = params.iter().map(|p| json_string(&p.name)).collect();
    out.push_str(&format!("const {names} = [{}];\n", names_literal.join(", ")));
    out.push_str(&format!("for (const __k of Object.keys({saved})) {{\n"));
    out.push_str(&format!(
        "  if ({names}.indexOf(__k) < 0) throw runtimeError(\"dejavu.template.unknown-parameter\", __k, {{ name: __k }});\n"
    ));
    out.push_str("}\n");
    out.push_str("ctx = {};\n");
    for param in params {
        let name = json_string(&param.name);
        match &param.default {
            Some(default) => {
                out.push_str(&format!(
                    "ctx[{name}] = Object.prototype.hasOwnProperty.call({saved}, {name}) ? {saved}[{name}] : {};\n",
                    emit_expr(default, ctx)
                ));
            }
            None => {
                out.push_str(&format!(
                    "if (!Object.prototype.hasOwnProperty.call({saved}, {name})) throw runtimeError(\"dejavu.template.missing-parameter\", {name}, {{ name: {name} }});\n"
                ));
                out.push_str(&format!("ctx[{name}] = {saved}[{name}];\n"));
            }
        }
    }
    emit_body(body, ctx, out, catalog);
    out.push_str(&format!("ctx = {saved};\n"));
    out.push_str("}\n");
}

fn emit_include(
    path_node: &IrNode,
    with: Option<&IrNode>,
    only: bool,
    ctx: &mut CodegenCtx,
    out: &mut String,
    catalog: Option<&CatalogEmitCtx>,
) {
    let Some(cat) = catalog else {
        emit_not_supported("Stmt.Include", None, ctx, out);
        return;
    };
    let Some(literal) = crate::catalog::extract_path_literal(path_node) else {
        ctx.diagnostic(
            Severity::Error,
            codes::INCLUDE_PATH_NOT_LITERAL,
            "`include` requires a literal template path",
        );
        return;
    };
    let Some(canonical_id) = cat.include_imports.get(&literal) else {
        ctx.diagnostic(
            Severity::Error,
            "dejavu.compile.include-not-resolved",
            format!("include path {literal:?} could not be resolved in catalog"),
        );
        return;
    };
    let binding = crate::catalog::js_import_name(canonical_id);
    // Include runtime contract: the included template's render(ctx, options)
    // returns a string; we spread it into __out.push for direct concatenation.
    // A partial target never inherits the caller context, so it receives the
    // explicit object only.
    let target_is_partial = cat.partial_ids.contains(canonical_id);
    let context_expr = if target_is_partial {
        match with {
            Some(expr) => format!("Object.assign({{}}, {})", emit_expr(expr, ctx)),
            None => "{}".to_string(),
        }
    } else {
        match (with, only) {
            // Default: inherit the caller context.
            (None, false) => "ctx".to_string(),
            // `only` / `without context` with no explicit object: empty context.
            (None, true) => "{}".to_string(),
            (Some(expr), isolated) => {
                let e = emit_expr(expr, ctx);
                if isolated {
                    format!("Object.assign({{}}, {e})")
                } else {
                    format!("Object.assign({{}}, ctx, {e})")
                }
            }
        }
    };
    // A partial may recurse into itself to render nested data. The depth limit
    // is the interpreter's constant, inlined here so both hosts share one bound.
    // Non-partial targets keep passing the current depth through.
    let depth = if target_is_partial {
        let limit = dejavu_ir::render::PARTIAL_RECURSION_LIMIT;
        out.push_str(&format!(
            "if (__partialDepth >= {limit}) throw runtimeError(\"{}\", {}, {{ limit: {limit} }});\n",
            codes::PARTIAL_RECURSION,
            json_string("partial recursion exceeded the limit")
        ));
        "__partialDepth + 1"
    } else {
        "__partialDepth"
    };
    out.push_str(&format!("__out.push({binding}({context_expr}, options, {depth}));\n"));
}

fn emit_super(
    ctx: &mut CodegenCtx,
    out: &mut String,
    catalog: Option<&CatalogEmitCtx>,
) {
    let Some(cat) = catalog else {
        emit_not_supported("Stmt.Super", None, ctx, out);
        return;
    };
    // `super` inlines the next ancestor definition of the enclosing block; the
    // index advances so a `super` inside that body resolves one level further.
    let index = ctx.super_index;
    let Some(body) = ctx.super_chain.get(index).cloned() else {
        // The root template does not define this block — output nothing.
        return;
    };
    let saved_index = ctx.super_index;
    ctx.super_index = index + 1;
    emit_body(&body, ctx, out, Some(cat));
    ctx.super_index = saved_index;
}

// ---------------------------------------------------------------------------
// If / ElseIf  (catalog-aware body propagation)
// ---------------------------------------------------------------------------

fn emit_if(
    test: &IrNode,
    consequent: &[IrNode],
    else_ifs: &[IrNode],
    alternate: Option<&[IrNode]>,
    ctx: &mut CodegenCtx,
    out: &mut String,
    catalog: Option<&CatalogEmitCtx>,
) {
    let test_expr = emit_expr(test, ctx);
    out.push_str(&format!("if (isTruthy({test_expr})) {{\n"));
    emit_body(consequent, ctx, out, catalog);
    out.push_str("}\n");

    for ei in else_ifs {
        if let IrNode::StmtElseIf { test: t, consequent: body, .. } = ei {
            let t_expr = emit_expr(t, ctx);
            out.push_str(&format!("else if (isTruthy({t_expr})) {{\n"));
            emit_body(body, ctx, out, catalog);
            out.push_str("}\n");
        } else {
            ctx.diagnostic(
                Severity::Error,
                "dejavu.compile.invalid-elseif",
                "elseIfs entry was not Stmt.ElseIf",
            );
        }
    }

    if let Some(alt) = alternate {
        out.push_str("else {\n");
        emit_body(alt, ctx, out, catalog);
        out.push_str("}\n");
    }
}

// ---------------------------------------------------------------------------
// For  (catalog-aware body propagation)
// ---------------------------------------------------------------------------

fn emit_for(
    item: &str,
    index: Option<&str>,
    iterable: &IrNode,
    body: &[IrNode],
    ctx: &mut CodegenCtx,
    out: &mut String,
    catalog: Option<&CatalogEmitCtx>,
) {
    // Unique temp names: two loops in one module body must not redeclare the
    // same `let` (that is a JS SyntaxError). The extra braces give every loop
    // its own block scope; nesting is therefore safe as well.
    let it_temp = ctx.next_temp();
    let item_has = format!("{it_temp}_item_has");
    let item_prev = format!("{it_temp}_item_prev");

    out.push_str("{\n");
    out.push_str(&format!("let {it_temp} = {};\n", emit_expr(iterable, ctx)));

    // Strict check is always emitted and gated by the runtime `__strict`
    // flag, so a caller-supplied `strictUndefined` can override the
    // build-time default.
    if let IrNode::ExprIdentifier { name, .. } = iterable {
        out.push_str(&format!(
            "if (__strict && {it_temp} === undefined) throw runtimeError(\"dejavu.template.undefined-variable\", {}, {{ name: {} }});\n",
            json_string(name),
            json_string(name)
        ));
    }

    // Save the caller context's own `item` slot before the loop overwrites it.
    out.push_str(&format!(
        "const {item_has} = Object.prototype.hasOwnProperty.call(ctx, {});\n",
        json_string(item)
    ));
    out.push_str(&format!(
        "const {item_prev} = {item_has} ? ctx[{}] : undefined;\n",
        json_string(item)
    ));

    let index_saved = index.map(|idx| {
        let has = format!("{it_temp}_index_has");
        let prev = format!("{it_temp}_index_prev");
        out.push_str(&format!(
            "const {has} = Object.prototype.hasOwnProperty.call(ctx, {});\n",
            json_string(idx)
        ));
        out.push_str(&format!(
            "const {prev} = {has} ? ctx[{}] : undefined;\n",
            json_string(idx)
        ));
        (idx, has, prev)
    });

    out.push_str(&format!("for (let __i = 0; __i < {it_temp}.length; __i++) {{\n"));
    out.push_str(&format!("ctx[{}] = {it_temp}[__i];\n", json_string(item)));
    if let Some((idx, _, _)) = &index_saved {
        out.push_str(&format!("ctx[{}] = __i;\n", json_string(idx)));
    }
    emit_body(body, ctx, out, catalog);
    out.push_str("}\n");

    // Restore the caller context: write back the old value when the key was
    // an own property, otherwise delete it (same as JIT scope restore).
    out.push_str(&format!(
        "if ({item_has}) ctx[{}] = {item_prev}; else delete ctx[{}];\n",
        json_string(item),
        json_string(item)
    ));
    if let Some((idx, has, prev)) = &index_saved {
        out.push_str(&format!(
            "if ({has}) ctx[{}] = {prev}; else delete ctx[{}];\n",
            json_string(idx),
            json_string(idx)
        ));
    }
    out.push_str("}\n");
}

// ---------------------------------------------------------------------------
// Interpolation
// ---------------------------------------------------------------------------

fn emit_interpolation(
    expression: &IrNode,
    raw: bool,
    ctx: &mut CodegenCtx,
    out: &mut String,
) {
    // Decision: pipe ending in raw/safe/escape OR raw=true → no htmlEscape wrap.
    // Otherwise htmlEscape(valueToString(__v)).
    let (expr_fragment, needs_escape) = analyze_interpolation(expression, raw, ctx);

    // Always eval into a temp for easy strict-check injection.
    let temp = ctx.next_temp();

    // Strict undefined check: when the *top-level expression* is an identifier,
    // we can name it for the error. Otherwise skip the named hint.
    //
    // The check is emitted unconditionally and gated by the runtime `__strict`
    // flag, so callers can turn strict mode on/off per render call regardless
    // of the build-time default.
    let strict_msg = match expression {
        IrNode::ExprIdentifier { name, .. } => Some(format!(
            "if (__strict && {temp} === undefined) throw runtimeError(\"dejavu.template.undefined-variable\", {}, {{ name: {} }});",
            json_string(name),
            json_string(name)
        )),
        _ => None,
    };

    out.push_str(&format!("let {temp} = {expr_fragment};\n"));
    if let Some(check) = strict_msg {
        out.push_str(&check);
        out.push('\n');
    }

    if needs_escape {
        out.push_str(&format!("__out.push(htmlEscape(valueToString({temp})));\n"));
    } else {
        out.push_str(&format!("__out.push(valueToString({temp}));\n"));
    }
}

/// Determine whether an interpolation needs htmlEscape wrapping.
///
/// Returns `(expression_fragment, needs_escape)`. `needs_escape=false` when the
/// expression's outer form is a pipe ending in `raw`/`safe`/`escape`/`e` (note:
/// the `escape`/`e` filter name is `escape` and we treat it as "already safe" —
/// that's how dejavu-engine interprets it: `escape` produces escaped HTML but
/// the interpolator auto-escapes, so a trailing escape filter means "do not
/// auto-escape").
///
/// The root-level `raw: true` flag also disables auto-escape unconditionally.
fn analyze_interpolation(
    expression: &IrNode,
    raw: bool,
    ctx: &mut CodegenCtx,
) -> (String, bool) {
    if raw {
        return (emit_expr(expression, ctx), false);
    }
    // A macro returns markup it rendered itself, so its invocation is already
    // safe output (the interpreter applies the same rule).
    if let IrNode::ExprCall { callee, .. } = expression {
        if let IrNode::ExprIdentifier { name, .. } = callee.as_ref() {
            if ctx.is_macro(name) || name == "caller" {
                return (emit_expr(expression, ctx), false);
            }
        }
    }
    match expression {
        IrNode::ExprPipe { filter, .. } => {
            // Only the outermost (final) filter decides escaping, via the
            // registry capability shared with the JIT renderer. Host-supplied
            // `safe-output` filters opt out of the automatic escape exactly like
            // built-in `raw` / `safe` / `escape`.
            let capability = dejavu_ir::registry::filter_spec(filter)
                .map(|spec| spec.capability)
                .or_else(|| {
                    custom_entry(ctx.custom_registry, Namespace::Filter, filter)
                        .map(|entry| entry.capability)
                });
            let no_escape = matches!(capability, Some(Capability::SafeOutput));
            (emit_expr(expression, ctx), !no_escape)
        }
        _ => (emit_expr(expression, ctx), true),
    }
}

// ---------------------------------------------------------------------------
// Macro functions
// ---------------------------------------------------------------------------

/// Identifier-safe rendering of a macro name.
fn macro_safe_name(name: &str) -> String {
    let mut safe: String = name
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() || c == '_' { c } else { '_' })
        .collect();
    if safe.is_empty() {
        safe.push('_');
    }
    if safe.chars().next().is_some_and(|c| c.is_ascii_digit()) {
        safe.insert(0, '_');
    }
    safe
}

/// JS function name for a macro declared in this module.
pub fn macro_fn_name(name: &str) -> String {
    format!("__macro_{}", macro_safe_name(name))
}

/// JS binding for a macro imported from another module.
pub fn macro_import_binding(name: &str) -> String {
    format!("__macro_import_{}", macro_safe_name(name))
}

/// Emit one JS function per top-level macro declaration.
///
/// Macro functions live at module scope so declarations produce no output
/// where they appear. Their body only sees the bound parameters (`ctx` is
/// rebuilt from `args`), matching the interpreter's lexical isolation.
pub fn emit_macro_functions(
    children: &[IrNode],
    ctx: &mut CodegenCtx,
    catalog: Option<&CatalogEmitCtx<'_>>,
) -> String {
    let mut out = String::new();
    let limit = dejavu_ir::render::MACRO_RECURSION_LIMIT;
    for child in children {
        let IrNode::StmtMacro { name, params, body, .. } = child else {
            continue;
        };
        let required = params.iter().filter(|p| p.default.is_none()).count();
        let max = params.len();
        out.push_str(&format!(
            "function {}(__invokeCtx, args, __depth, __strict, __caller, __custom) {{\n",
            macro_fn_name(name)
        ));
        out.push_str(&format!(
            "if (__caller == null) __caller = function () {{ throw runtimeError(\"dejavu.template.caller-unavailable\", {}); }};\n",
            json_string(&format!("macro `{name}` was invoked without a caller block"))
        ));
        if max > 0 {
            out.push_str(&format!(
                "if (args.length > {max}) throw runtimeError(\"dejavu.template.macro-arity\", {}, {{ macro: {}, minArgs: {required}, maxArgs: {max}, got: args.length }});\n",
                json_string(&format!("macro `{name}` expects {required}..{max} argument(s)")),
                json_string(name)
            ));
        }
        for (i, param) in params.iter().enumerate() {
            if param.default.is_none() {
                out.push_str(&format!(
                    "if (args.length <= {i}) throw runtimeError(\"dejavu.template.missing-macro-argument\", {}, {{ macro: {}, name: {} }});\n",
                    json_string(&format!("macro `{name}` requires `{}`", param.name)),
                    json_string(name),
                    json_string(&param.name)
                ));
            }
        }
        out.push_str(&format!(
            "if (__depth > {limit}) throw runtimeError(\"dejavu.template.macro-recursion\", {}, {{ macro: {}, limit: {limit} }});\n",
            json_string(&format!("macro `{name}` exceeded the recursion limit")),
            json_string(name)
        ));

        out.push_str("const ctx = {};\n");
        for (i, param) in params.iter().enumerate() {
            let value = match &param.default {
                Some(IrNode::ExprLiteral { value, .. }) => emit_json_value(value),
                _ => "undefined".into(),
            };
            out.push_str(&format!(
                "ctx[{}] = args.length > {i} ? args[{i}] : {value};\n",
                json_string(&param.name)
            ));
        }

        let mut inner = CodegenCtx::new(ctx.options);
        inner.macros = ctx.macros.clone();
        inner.macro_depth_expr = "__depth + 1".into();
        inner.in_macro = true;
        let mut body_str = String::new();
        emit_body(body, &mut inner, &mut body_str, catalog);
        ctx.diagnostics.extend(inner.diagnostics);

        out.push_str("const __out = [];\n");
        out.push_str(&body_str);
        out.push_str("return __out.join(\"\");\n");
        out.push_str("}\n\n");
    }
    out
}

// ---------------------------------------------------------------------------
// Unsupported-node placeholder
// ---------------------------------------------------------------------------

fn emit_not_supported(
    node_kind: &str,
    extra: Option<&str>,
    ctx: &mut CodegenCtx,
    out: &mut String,
) {
    let detail = if let Some(e) = extra {
        format!("{node_kind} ({e})")
    } else {
        node_kind.to_string()
    };
    let msg = format!("dejavu.compile.not-supported-in-single-template: {detail}");
    ctx.diagnostic(Severity::Error, msg.clone(), msg.clone());
    out.push_str(&format!(
        "throw runtimeError(\"dejavu.compile.not-supported-in-single-template\", {});\n",
        json_string(&detail)
    ));
}

